const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2023-01-01';
    const end = '2024-01-01';
    const thresholdHa = 160000;

    // Quebec geometry (try GAUL, then GADM)
    let regionSource = null;
    let region = null;

    const gaul = ee.FeatureCollection('FAO/GAUL/2015/level1')
      .filter(ee.Filter.eq('ADM0_NAME', 'Canada'))
      .filter(ee.Filter.inList('ADM1_NAME', ['Quebec', 'Québec', 'Quebec (Province de)']));
    const gaulCount = await gaul.size().getInfo();
    if (gaulCount > 0) {
      regionSource = 'GAUL/2015/level1';
      region = gaul.geometry();
    } else {
      const gadm = ee.FeatureCollection('GADM/2018/1')
        .filter(ee.Filter.eq('GID_0', 'CAN'))
        .filter(ee.Filter.inList('NAME_1', ['Quebec', 'Québec']));
      const gadmCount = await gadm.size().getInfo();
      if (gadmCount > 0) {
        regionSource = 'GADM/2018/1';
        region = gadm.geometry();
      } else {
        console.log('Region lookup failed: Quebec not found in GAUL or GADM.');
        console.log('D');
        return;
      }
    }

    // 2. Data Acquisition & Check
    let datasetId = 'MODIS/061/MCD64A1';
    let col = ee.ImageCollection(datasetId).filterDate(start, end);
    let n061 = await col.size().getInfo();
    if (n061 === 0) {
      // Fallback to 006
      datasetId = 'MODIS/006/MCD64A1';
      col = ee.ImageCollection(datasetId).filterDate(start, end);
    }
    const nImgs = await col.size().getInfo();
    console.log(`Region source: ${regionSource}`);
    console.log(`Dataset: ${datasetId}`);
    console.log(`2023 Images: ${nImgs}`);

    if (nImgs === 0) {
      console.log('C1');
      return;
    }

    // 3. Processing
    const bdMax = col.select('BurnDate').max(); // Max DOY in 2023 per pixel
    // Available pixels (non-null BurnDate domain at this scale)
    const availableCount = await bdMax.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 2e13
    }).get('BurnDate').getInfo();

    if (availableCount === null || availableCount === 0) {
      console.log('Available pixels: 0');
      console.log('C2');
      return;
    }

    // Burned mask and stats
    const burnedBinary = bdMax.gt(0).rename('burned').selfMask();
    const burnedCount = await burnedBinary.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 2e13
    }).get('burned').getInfo();

    // Area (ha) - unmask to 0 so null becomes 0 when no burned pixels
    const areaHaImg = ee.Image.pixelArea().divide(10000).rename('area').updateMask(burnedBinary).unmask(0);
    const areaDict = await areaHaImg.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 1000,
      maxPixels: 2e13
    }).getInfo();

    const burnedAreaHaRaw = areaDict ? areaDict['area'] : null;
    if (burnedAreaHaRaw === null || Number.isNaN(burnedAreaHaRaw)) {
      console.log('Burned area (ha): null');
      console.log('C3');
      return;
    }
    const burnedAreaHa = burnedAreaHaRaw;

    // 4. Validation & Evidence
    const burnedPct = (burnedCount && availableCount) ? (100 * burnedCount / availableCount) : 0;
    console.log(`Available pixels (1km samp.): ${availableCount}`);
    console.log(`Burned pixels: ${burnedCount || 0} (${burnedPct.toFixed(3)}%)`);
    console.log(`Burned area 2023 (ha): ${Math.round(burnedAreaHa).toLocaleString()}`);
    console.log(`Threshold (ha): ${thresholdHa.toLocaleString()}`);

    // 5. Final Answer
    if (!isFinite(burnedAreaHa)) {
      console.log('C3');
      return;
    }
    if (burnedAreaHa > thresholdHa) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
